import React from 'react';

export default function MeritListSection() {
  const plans = [
    {
      label: "B PHARMACY",
      pdfBase64: "",
      description:
        "View the official B Pharmacy Merit List containing the finalized list of shortlisted candidates based on academic qualifications.",
    },
    {
      label: "D PHARMACY",
      pdfBase64: "",
      description:
        "Access the D Pharmacy Merit List with complete details of eligible students selected for the academic year.",
    },
    {
      label: "DSY FINAL MERIT LIST",
      pdfBase64: "",
      description:
        "Check the DSY (Direct Second Year) Final Merit List including updated rankings and allotments.",
    },
  ];

  // Opens Base64 PDF in a new tab
  const openBase64PDF = (base64) => {
    const pdfWindow = window.open();
    pdfWindow.document.write(
      `<iframe width='100%' height='100%' src='data:application/pdf;base64,${base64}'></iframe>`
    );
  };

  return (
    <div className="min-h-fit py-16 px-4">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-5xl md:text-6xl font-normal text-center text-gray-900 mb-16">
          Merit Lists
        </h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {plans.map((plan, index) => (
            <div
              key={index}
              className="bg-white rounded-3xl shadow-lg p-8 flex flex-col"
            >
              <div className="inline-flex items-center gap-2 bg-gray-100 rounded-full px-4 py-2 mb-6 self-start">
                <div className="w-2 h-2 bg-green-600 rounded-full"></div>
                <span className="text-sm font-medium text-gray-700 tracking-wider">
                  {plan.label}
                </span>
              </div>

              <p className="text-gray-500 leading-relaxed mb-8 flex-grow">
                {plan.description}
              </p>

              <button
                onClick={() => openBase64PDF(plan.pdfBase64)}
                className="w-full bg-black text-white font-medium py-4 rounded-full hover:bg-gray-800 transition-colors duration-200"
              >
                View Merit List
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
